    'DynamicIncidentReportDesc'  => 'Creador d\'informes configurable per a incidents amb controls de columna, filtre i agrupació.',
    'LessonsLearnedDesc'         => 'Lliçons apreses recollides en tots els incidents, amb el context de l\'incident d\'origen.',
