    // Configure Hub - tile descriptions (system category)
    'SettingsDesc'                        => 'Configureu els paràmetres de tot el sistema: URL base, seguretat, idioma per defecte, fus horari, valors per defecte de la puntuació del risc i més.',
    'SettingsPreferencesDesc'             => 'Valors per defecte i preferències de comportament a SimpleRisk: idioma, fus horari, estats d\'auditoria, requisits d\'assignació de riscos, opcions de comportament de la interfície i similars.',
    'SettingsFileUploadDesc'              => 'Tipus de fitxers permesos per a la pujada i límits de mida per als diversos camps d\'adjunció de fitxers.',
    'SettingsMailDesc'                    => 'Configuració SMTP per a les notificacions per correu electrònic sortints, incloent-hi el transport, l\'amfitrió, l\'autenticació i l\'adreça de resposta.',
    'SettingsBackupsDesc'                 => 'Configura la retenció de còpies de seguretat, la programació i els enllaços de descàrrega per a les còpies de seguretat de la base de dades SimpleRisk.',
    'SettingsSecurityDesc'                => 'Configuració de seguretat de l\'autenticació, la sessió, la política de contrasenyes, l\'URL base i l\'API.',
    'SettingsLoggingDesc'                 => 'Configuració del registre de depuració i auditoria: nivells de registre, retenció i ubicació dels fitxers de registre.',
    'HealthCheckDesc'                     => 'Diagnosticar l\'estat del sistema: versió de PHP, extensions, permisos de fitxers, connectivitat de la base de dades, programació cron i activacions addicionals.',
    'AnnouncementsDesc'                   => 'Redacta i gestiona anuncis de bàner visibles per a tots els usuaris.',
    'RegisterAndUpgradeDesc'              => 'Registreu la vostra instal·lació de SimpleRisk, introduïu o renoveu una clau de subscripció i inicieu actualitzacions del Core i dels Extras amb un sol clic.',
    'QueueMonitorDesc'                    => 'Inspeccioneu la cua de tasques en segon pla: tasques pendents, en curs i fallides.',
    'ExtrasDesc'                          => 'Activeu, desactiveu i configureu els Extras de SimpleRisk (complements de pagament).',
    'ArtificialIntelligenceExtraDesc'     => 'L\'Extra d\'intel·ligència artificial ofereix una anàlisi de riscos millorada (incloent-hi avaluacions FAIR) i documentació personalitzada.',
    'CustomizationExtraDesc'              => 'L\'Extra de personalització permet afegir i eliminar diferents tipus de camps i crear dinàmicament plantilles de pàgina personalitzades.',
    'NotificationExtraDesc'               => 'L\'Extra de notificacions per correu electrònic permet a SimpleRisk enviar notificacions per correu electrònic quan s\'envien, es modifiquen o s\'actua d\'alguna altra manera sobre els riscos. Aquest Extra també es pot afegir com a script programat per enviar recordatoris periòdics quan els riscos estan preparats per a una revisió de gestió. Al producte SimpleRisk Core, sense aquest Extra, no es comunica cap notificació fora de l\'eina.',
    'VulnerabilityManagementExtraDesc'    => 'L\'Extra de gestió de vulnerabilitats ofereix als clients la capacitat d\'integrar la seva instància de SimpleRisk amb Qualys, Tenable.io o Rapid7 Nexpose/InsightVM i d\'importar a SimpleRisk tant dades d\'actius com de vulnerabilitats. A partir d\'aquí, podeu seleccionar quins llocs voleu cobrir, determinar quines puntuacions de vulnerabilitat s\'han d\'importar i triar quines vulnerabilitats es converteixen en riscos per fer-ne el seguiment.',
    'IncidentManagementExtraDesc'         => 'L\'Extra de gestió d\'incidents es basa en la guia NIST 800-61 de gestió d\'incidents de seguretat informàtica i ofereix capacitats de gestió d\'incidents des del sistema SimpleRisk.',

    // Configure Hub - tile descriptions (customization category)
    'RedefineNamingConventionsDesc'       => 'Canvieu el nom de la terminologia de SimpleRisk (risc, actiu, marc, etc.) a tota la interfície.',
    'RiskConfigurationDesc'               => 'Configureu les regles de puntuació del risc: nivells, apetit, llindars d\'SLA i les fórmules de risc clàssica i de factors contribuents.',
    'RiskAndThreatCatalogDesc'            => 'Mantingueu el catàleg de valors de risc i amenaça utilitzats als menús desplegables.',
    'AddAndRemoveValuesDesc'              => 'Gestioneu els valors dels desplegables dels camps de risc: ubicació, origen, categoria, equip, tecnologia i més.',
    'AssetValuationDesc'                  => 'Configureu l\'escala de valoració d\'actius i les substitucions de valoració per actiu.',

    // Configure Hub - tile descriptions (users category)
    'UserManagementDesc'                  => 'Afegir, editar, desactivar i restablir usuaris; gestionar la política de contrasenyes.',
    'RoleManagementDesc'                  => 'Definir els rols i els permisos que atorga cada rol.',
    'TeamManagementDesc'                  => 'Crea i gestiona equips utilitzats per al filtratge de visibilitat de registres.',
    'SeparationExtraDesc'                 => 'L\'Extra de separació basada en equips restringeix la visualització de riscos només als usuaris que són membres de l\'equip al qual s\'ha assignat el risc. Al producte SimpleRisk Core, sense aquest Extra, tots els usuaris poden veure tots els riscos.',
    'CustomAuthenticationExtraDesc'       => 'L\'Extra d\'autenticació personalitzada proporciona compatibilitat amb l\'autenticació d\'Active Directory i SAML. Al producte SimpleRisk Core, sense aquest Extra, l\'única opció és crear nous usuaris al repositori d\'identitats de SimpleRisk.',
    'EncryptionExtraDesc'                 => 'L\'Extra de base de dades xifrada genera una clau de xifratge AES-256 bits aleatòria i l\'utilitza per xifrar el text sensible abans d\'inserir-lo a la base de dades de SimpleRisk. Això impedeix que ningú pugui veure o modificar les dades sense utilitzar directament l\'aplicació SimpleRisk.',
    'OrganizationManagementDesc'          => "L'Extra de Jerarquia Organitzativa permet definir diverses unitats de negoci que poden incloure qualsevol nombre d'equips. Aleshores, els usuaris poden ser assignats a un o més equips sota diverses unitats de negoci. Això afecta la capacitat d'un usuari per veure i utilitzar els equips, els usuaris i els actius amb els quals no està associat.",

    // Configure Hub - tile descriptions (data category)
    'DeleteRisksDesc'                     => 'Elimineu riscos de manera massiva. Utilitzeu-ho amb moderació: les eliminacions són permanents.',
    'AuditTrailDesc'                      => 'Cerqueu i exporteu el registre d\'auditoria del sistema amb les accions dels usuaris.',
    'ImportExportExtraDesc'               => 'L\'Extra d\'importació i exportació ofereix la capacitat d\'importar dades a SimpleRisk mitjançant l\'assignació de camps d\'un fitxer CSV als camps de la base de dades de SimpleRisk. Es pot utilitzar per importar resultats d\'auditoria d\'un full de càlcul de tercers, resultats d\'escaneig de vulnerabilitats d\'una altra eina, actius del vostre CMDB i més. L\'Extra també ofereix la capacitat d\'exportar fitxers CSV de SimpleRisk que continguin riscos, mitigacions, revisions o un informe combinat dels tres.',
    'JiraExtraDesc'                       => 'L\'Extra d\'integració amb Jira ofereix als usuaris la capacitat d\'integrar-se de manera bidireccional amb una instància de Jira. Permet connectar riscos amb incidències de Jira, així com sincronitzar-ne les dades, l\'estat i els comentaris.',
    'APIExtraDesc'                        => 'L\'Extra d\'API permet als clients utilitzar una API RESTful per crear interaccions programades amb altres aplicacions i obtenir una automatització avançada i aprofitar la infraestructura existent.',
    'AdvancedSearchExtraDesc'             => 'L\'Extra de cerca avançada converteix el quadre de cerca de la barra superior en una única cerca entre riscos, marcs, controls, documents, excepcions, proves, auditories, actius i grups d\'actius, amb una pàgina de cerca completa per treballar amb els resultats. Només mostra els registres que l\'usuari té permès veure.',
    'AssessmentsExtraDesc'                => 'L\'Extra d\'avaluació de riscos ofereix als usuaris la capacitat de definir contactes, crear preguntes (incloent-hi lògica), agrupar diverses preguntes amb una plantilla de qüestionari, crear qüestionaris i enviar-los als contactes, veure els resultats dels qüestionaris, afegir riscos basats en aquests resultats, comparar els resultats al llarg del temps, importar i exportar avaluacions personalitzades externament i revisar el registre d\'auditoria de l\'avaluació de riscos.',
    'ActiveAssessmentsDesc'               => 'Visualitza i gestiona les avaluacions actualment en curs.',
    'WorkflowsExtraDesc'                  => 'L\'Extra de fluxos de treball ofereix un motor de fluxos de treball visual i basat en esdeveniments que automatitza les accions de gestió de riscos en resposta a esdeveniments dins de SimpleRisk. Podeu dissenyar fluxos de treball que s\'activin davant de canvis (com ara un risc enviat, actualitzat o revisat) per encaminar aprovacions, assignar tasques i mantenir el procés en marxa sense intervenció manual.',

    // Configure Hub - tile descriptions (frameworks category)
    'SCFExtraDesc'                        => 'L\'Extra Secure Controls Framework (SCF) és una integració directa entre el Secure Controls Framework i SimpleRisk. Importa el catàleg de controls de l\'SCF i les seves correspondències amb una àmplia gamma de marcs de compliment i de ciberseguretat a la funcionalitat de Governança de SimpleRisk, de manera que pugueu adoptar els marcs que necessiteu i gestionar-ne els controls sense haver de crear-los manualment.',

    // Configure Hub - tile descriptions (maintenance category)
    'FixReviewDatesDesc'                  => 'Migra les columnes heretades de data de revisió de tipus varchar a tipus de data adequats. Només és visible quan cal.',
    'DatabaseUpgradeDesc'                 => 'Activeu manualment la rutina d\'actualització de la base de dades de SimpleRisk.',

