    'EncryptionMissingLockTablesPrivilegeUi' => 'L\'usuari de la base de dades de SimpleRisk no té el privilegi LOCK TABLES necessari per al xifratge. Un administrador de la base de dades ha d\'executar: GRANT LOCK TABLES ON {$db}.* TO {$user}; i després tornar-ho a provar.',
    'EncryptionRequiredGrantLabel' => 'Sentència GRANT requerida:',
