    'EncryptionStageEncryptTable'           => 'Xifra la taula: {table}',
    'EncryptionStageDecryptTable'           => 'Desxifra la taula: {table}',
    'EncryptionActivationInProgress'        => 'S\'està xifrant la base de dades SimpleRisk. Si us plau, no tanqueu aquesta pàgina.',
    'EncryptionActivationFailedTitle'       => 'L\'activació del xifratge ha fallat',
    'EncryptionActivationFailedBody'        => 'L\'activació no s\'ha pogut completar i és possible que la base de dades estigui en un estat inconsistent. Es conserva la còpia de seguretat prèvia a l\'activació; utilitzeu Restaura des de la còpia de seguretat per recuperar-la o poseu-vos en contacte amb el suport tècnic de SimpleRisk.',
    'EncryptionDeactivationInProgress'      => 'S\'està desxifrant la vostra base de dades de SimpleRisk. No tanqueu aquesta pàgina.',
    'EncryptionDeactivationFailedTitle'     => 'La desactivació del xifratge ha fallat',
    'EncryptionDeactivationFailedBody'      => 'La desactivació no s\'ha pogut completar i és possible que la base de dades es trobi en un estat inconsistent. La còpia de seguretat en estat xifrat es conserva; utilitzeu Restaura des de la còpia de seguretat per tornar a l\'estat xifrat o poseu-vos en contacte amb el suport de SimpleRisk.',
    'RestoreFromBackup'                     => 'Restaurar des d\'una còpia de seguretat',
    'RestoreFromBackupNotYetAvailable'      => 'Restaurar des de la còpia de seguretat encara no està disponible en aquesta compilació. Contacteu amb el suport de SimpleRisk per recuperar les dades.',
    'EncryptionRestoreInProgress'           => 'S\'està restaurant la vostra base de dades de SimpleRisk des de la còpia de seguretat. Això pot trigar diversos minuts.',
    'EncryptionRestoreEnqueueFailed'        => 'No s\'ha pogut iniciar la restauració. Reviseu els registres de SimpleRisk i torneu-ho a provar.',
    'EncryptionStatusActive'                => 'L\'extra de base de dades xifrada està actiu.',
    'EncryptionStatusVersion'               => 'Versió',
    'EncryptionDeactivateCta'               => 'Desactiva l\'extra de la base de dades xifrada',
    'EncryptionDeactivateCtaHelp'           => 'Desxifra cada columna xifrada i la retorna a text sense xifrar. Això triga uns minuts en una base de dades amb dades.',
    'EncryptionBackupPanelHeading'          => 'Còpia de seguretat prèvia a l\'activació',
    'EncryptionBackupCreatedAt'             => 'Creat',
    'EncryptionBackupSize'                  => 'Mida',
    'EncryptionBackupOriginalFilename'      => 'Fitxer',
    'EncryptionBackupDownloadTooltip'       => 'Feu clic per descarregar una còpia d\'aquest fitxer de còpia de seguretat per emmagatzemar-la fora de línia.',
    'EncryptionBackupStateRestoring'        => 'Actualment s\'està duent a terme una restauració.',
    'EncryptionNoBackupAvailable'           => 'Actualment no hi ha cap còpia de seguretat prèvia a l\'activació emmagatzemada. La còpia de seguretat es crea a l\'inici de cada activació i se sobreescriu amb qualsevol activació o desactivació posterior.',
    'EncryptionRestoreCtaHelp'              => 'Trieu aquesta opció si la validació ha trobat problemes i heu de tornar a l\'estat previ al xifratge.',
    'EncryptionRestoreTitle'                => 'Restaurar des d\'una còpia de seguretat?',
    'EncryptionRestoreBodyWhy'              => 'Es tornarà a la instantània prèvia al xifratge capturada a l\'inici de l\'activació més recent. Trieu aquesta opció si la validació posterior a l\'activació ha trobat problemes i heu d\'abandonar el xifratge.',
    'EncryptionRestoreBodyWhat'             => 'Totes les files escrites a la base de dades després de la creació de la còpia de seguretat es perdran permanentment, inclosos els riscos, les mitigacions, les entrades del registre d\'auditoria i qualsevol altre canvi realitzat des de l\'activació. L\'extra de la base de dades xifrada es desactivarà com a part de la restauració.',
    'EncryptionDeleteBackupCta'             => 'Suprimeix la còpia de seguretat prèvia al xifratge',
    'EncryptionDeleteBackupCtaHelp'         => 'Trieu aquesta opció quan hàgiu completat la validació posterior al xifratge. Eliminar la instantània sense xifrar és el que fa que el xifratge sigui realment protector.',
    'EncryptionDeleteBackupTitle'           => 'Voleu suprimir la còpia de seguretat prèvia al xifratge?',
    'EncryptionDeleteBackupBodyWhy'         => 'Eliminar la instantània sense xifrar de les dades que es va capturar a l\'inici de l\'activació més recent. Conservar-la indefinidament frustra l\'objectiu del xifratge: qualsevol persona amb accés a la base de dades pot llegir la còpia prèvia al xifratge.',
    'EncryptionDeleteBackupBodyWhat'        => 'La còpia de seguretat de la base de dades se suprimeix immediatament. Ja no podreu usar Restaurar des de la còpia de seguretat per tornar la base de dades a l\'estat previ al xifratge. Si més endavant trobeu problemes amb el xifratge, l\'única via de recuperació serà una restauració completa de la base de dades a partir de les vostres còpies de seguretat operatives.',
