    'ControlIdOrShortNameFieldRequired' => 'Cal assignar el camp ID de control o Nom abreujat de control; no es pot identificar una fila sense un d\'ells.',
    'RiskImportSubjectNull' => 'ID de risc {$risk_id}: No s\'ha actualitzat perquè el camp Assumpte està buit o no hi és.',
    'RiskImportSummary' => 'S\'han enviat {$submitted} riscos i s\'han actualitzat {$updated} riscos.',
    'ControlImportSummary' => 'S\'han creat {$created} control(s) i s\'han actualitzat {$updated} control(s).',
    'ImportAdditionalIssuesSuppressed' => '{$count} files addicionals tenien problemes que no es mostren individualment aquí.',
    'EncryptionPipelineStalledTask' => 'Un procés de xifratge (tasca #{$id}, {$type}) sembla encallat: fa un temps inusualment llarg que està {$status} sense progressar. Normalment això vol dir que el treballador de la cua en segon pla no s\'està executant; comproveu que estigui programat i torneu-ho a provar quan hagi processat la tasca encallada.',
    'EncryptionPipelineStalledState' => 'Un procés de xifratge sembla encallat: fa un temps inusualment llarg que està marcat com a en curs i no hi ha cap tasca en segon pla corresponent. Normalment això vol dir que el treballador de la cua no s\'està executant, o que un procés anterior ha acabat sense actualitzar-ho correctament. Reviseu el registre de depuració abans de tornar-ho a provar.',
    // DEMO_MODE — shown when a visitor to a shared demo instance attempts one
