    // The one-click upgrade progress screen
    'UpgradeInProgress' => 'En curs',
    'UpgradeStepNotNeeded' => 'No cal',
    // Recovering an Upgrade Extra whose files are damaged
    'UpgradeExtraDamagedReinstalling' => 'L\'Extra d\'actualització instal·lat està malmès. S\'està descarregant una còpia nova.',
    'UpgradeExtraDamagedRepaired' => 'L\'Extra d\'actualització s\'ha substituït per una còpia que funciona.',
    'UpgradeExtraDamagedFailed' => 'L\'Extra d\'actualització està malmès i no s\'ha pogut substituir automàticament. Torneu-lo a instal·lar des de la pàgina d\'Extras, o restaureu simplerisk/extras/upgrade/ des d\'una còpia de seguretat, i torneu-ho a provar.',
    'UpgradeAlreadyCurrent' => 'Aquesta instància ja es troba a {version}, que és la versió més recent. No calia actualitzar res.',
    'UpgradeShowWhatItDid' => 'Mostra què va fer',
    'UpgradeBackupsListed' => 'Aquestes còpies de seguretat apareixen a Configura > Còpies de seguretat.',
    'UpgradingTo' => 'Actualització a {version}',
    'UpgradeSafeToClose' => 'Podeu tancar aquesta finestra sense problemes. L\'actualització continua al servidor i aquesta pàgina es tornarà a connectar.',
    'UpgradeDownloadLog' => 'Descarrega el registre',
    'UpgradeStatementsApplied' => 'Iniciat {started} · {count} instruccions aplicades',
    // The Upgrade Extra's pre-upgrade check of the instance it is sitting on
    'UpgradeCheckingInstance' => 'Comprovació d\'aquesta instància',
    'UpgradeInstanceChecked' => 'Instància revisada, no calen correccions.',
    'UpgradeBlockedByCorrections' => 'L\'actualització s\'ha aturat perquè aquesta instància necessita una correcció que no s\'ha pogut aplicar automàticament. Seguiu les instruccions anteriors i torneu a executar l\'actualització. No s\'ha canviat res més.',
    // Shown when an upgrade replaced the instance's configuration file and could not put the original back
