    'BackupDatabaseNative' => 'S\'està fent una còpia de seguretat de la base de dades (no calen eines externes)...',
    'UpgradeAlreadyRunning' => 'Ja hi ha una actualització en execució en aquesta instància.',
    'UpgradeStatusUnreachable' => 'S\'ha perdut el contacte amb el servidor mentre l\'actualització estava en execució. Reviseu el registre de SimpleRisk; és possible que l\'actualització encara estigui en curs.',
    'UpgradeJobUnwritable' => 'L\'actualització no s\'ha pogut iniciar perquè no s\'ha pogut escriure el registre de progrés. Comproveu que l\'usuari web pugui escriure al directori temporal del sistema.',
