    'LayoutEditorHint' => 'Arrossegueu un camp a una targeta diferent per reassignar-lo, arrossegueu dins d\'una targeta per reordenar-lo o redimensionar-lo, i arrossegueu o redimensioneu una targeta per canviar-ne la posició a la pàgina.',
