    'AssetScoring' => 'Puntuació d\'actius',
    'AssetScoringSettingsHint' => 'Cada actiu es valora com a Baix, Moderat o Alt en confidencialitat, integritat i disponibilitat, i la confidencialitat pot ser en canvi No aplicable, cosa que l\'exclou dels dos resultats. La seva categorització FIPS és la més alta de les tres valoracions. La seva puntuació ponderada és la mitjana ponderada dels tres valors de nivell, i els llindars de franja converteixen aquesta puntuació en una franja Baixa, Moderada o Alta. Canviar aquestes configuracions torna a puntuar immediatament tots els actius.',
    'Weights' => 'Pesos',
    'AssetScoringWeightsHint' => 'Quant compta cada objectiu en la puntuació ponderada: de 0 a 100, amb un màxim de dos decimals. Un pes de 0 deixa fora aquest objectiu. La integritat i la disponibilitat no poden ser 0 alhora, perquè sempre s\'omet una confidencialitat No aplicable.',
    'LevelValues' => 'Valors de nivell',
