    'AssetScoringScoreHelp' => 'La puntuació ponderada combina les tres valoracions en un únic número des de {$low} fins a {$high}. Cada valoració es converteix en el seu valor establert i es multiplica pel pes del seu objectiu. Els resultats se sumen i es divideixen pel total dels pesos. Una Confidencialitat No aplicable s\'exclou, juntament amb el seu pes. Els valors establerts i els pesos es configuren a Preferències. Cal valorar els tres objectius abans de mostrar una puntuació.',
    'AssetScoringCategorizationHelp' => 'La categorització de seguretat FIPS 199 és la marca màxima: la valoració més alta entre els objectius aplicables. Una sola valoració Alta fa que l\'actiu sigui Alt, independentment de les altres. No aplicable s\'ignora.',
