    // SR-115: HTTP Strict Transport Security (HSTS)
    'EnableHSTS' => 'Activa la seguretat de transport estricta HTTP (HSTS)',
    'EnableHSTSHelp' => 'Indica als navegadors que només es connectin a SimpleRisk mitjançant HTTPS durant l\'edat màxima indicada a continuació. Habiliteu-ho només quan HTTPS funcioni de manera fiable en aquest lloc: els navegadors que hagin vist la capçalera rebutjaran HTTP sense xifrar, i un certificat defectuós no es podrà evitar fins que l\'edat màxima expiri. Comenceu amb una edat màxima curta, com 300 segons, i augmenteu-la quan HTTPS estigui verificat.',
